module comparator_4bit(
    input [3:0] A, B,
    output A_greater, A_equal, A_less
);
    // Intermediate signals for subtraction results
    wire [3:0] subtract_result;
    wire carry_out;

    // Perform subtraction operation
    assign {carry_out, subtract_result} = A - B;

    // Determine comparison results based on subtraction result
    assign A_greater = ~carry_out & |subtract_result;
    assign A_equal = ~(|subtract_result);
    assign A_less = carry_out;
endmodule
